import{_ as e,o as n,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Test Specification — FR 3.10.2: Platform Statistics Overview","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-2-platform-statistics-overview/test.md","filePath":"feature/admin-management/3-10-2-platform-statistics-overview/test.md"}'),l={name:"feature/admin-management/3-10-2-platform-statistics-overview/test.md"};function s(d,t,o,r,c,g){return n(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="test-specification-—-fr-3-10-2-platform-statistics-overview" tabindex="-1">Test Specification — FR 3.10.2: Platform Statistics Overview <a class="header-anchor" href="#test-specification-—-fr-3-10-2-platform-statistics-overview" aria-label="Permalink to &quot;Test Specification — FR 3.10.2: Platform Statistics Overview&quot;">​</a></h1><h2 id="_1-traceability-execution-summary" tabindex="-1">1. Traceability &amp; Execution Summary <a class="header-anchor" href="#_1-traceability-execution-summary" aria-label="Permalink to &quot;1. Traceability &amp; Execution Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR ID</strong></td><td style="text-align:left;"><code>FR 3.10.2</code></td></tr><tr><td style="text-align:left;"><strong>Function Name</strong></td><td style="text-align:left;">Platform Statistics Overview</td></tr><tr><td style="text-align:left;"><strong>Functional Domain</strong></td><td style="text-align:left;">Admin</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Target Class &amp; Method</strong></td><td style="text-align:left;"><code>AdminStatisticsService.overview()</code> (40 LOC)</td></tr><tr><td style="text-align:left;"><strong>Unit Test File</strong></td><td style="text-align:left;"><code>brandhub-business-service/src/test/java/com/brandhub/business/service/admin/AdminStatisticsServiceTest.java</code></td></tr><tr><td style="text-align:left;"><strong>Code &amp; Test Author</strong></td><td style="text-align:left;">Ân</td></tr><tr><td style="text-align:left;"><strong>Test Requirement</strong></td><td style="text-align:left;">Return platform-wide operational KPIs: total users, active agencies and workspaces, strike counts, and registration trends</td></tr><tr><td style="text-align:left;"><strong>Preconditions</strong></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role</td></tr><tr><td style="text-align:left;"><strong>Overall Status</strong></td><td style="text-align:left;"><strong>Passed (100%)</strong></td></tr><tr><td style="text-align:left;"><strong>Test Case Breakdown</strong></td><td style="text-align:left;"><strong>Total: 16</strong> (<code>Passed</code>: 16, <code>Failed</code>: 0, <code>Untested</code>: 0) — <code>Normal (N)</code>: 6, <code>Boundary (B)</code>: 5, <code>Abnormal (A)</code>: 5</td></tr></tbody></table><hr><h2 id="_2-unit-test-case-matrix-utcid01–utcid16" tabindex="-1">2. Unit Test Case Matrix (<code>UTCID01</code>–<code>UTCID16</code>) <a class="header-anchor" href="#_2-unit-test-case-matrix-utcid01–utcid16" aria-label="Permalink to &quot;2. Unit Test Case Matrix (`UTCID01`–`UTCID16`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Test Case ID</th><th style="text-align:center;">Type</th><th style="text-align:left;">Preconditions</th><th style="text-align:left;">Test Inputs</th><th style="text-align:left;">Expected Return / Exception</th><th style="text-align:left;">Log Message</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><code>UTCID01</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Users, payments and agencies exist</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - totalUsers, newUsersByDay, revenueByMonth, activeAgencies</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID02</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Users, payments and agencies exist</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - totalUsers equals count of all non-deleted users</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID03</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Payments exist in several months</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - revenueByMonth has one entry per month with payments</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID04</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Agencies with ACTIVE and INACTIVE status</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - activeAgencies counts only ACTIVE agencies</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID05</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Users created on different days</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - newUsersByDay grouped by createdAt date</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID06</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Users on FREE and PRO plans</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - plan distribution matches subscriptions</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID07</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; System has no data</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - totalUsers=0, revenueByMonth=[], activeAgencies=0</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID08</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Exactly one user exists</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - totalUsers=1, newUsersByDay has 1 entry</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID09</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Payments in each of last 12 months</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - revenueByMonth has 12 entries</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID10</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; All users are soft-deleted</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - totalUsers=0 when all users soft-deleted</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID11</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Payment at 23:59:59 on last day of month</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">200 OK - month-end payment counted in correct month</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID12</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller does not have ADMIN system role</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">BusinessException(FORBIDDEN) - Your role does not have permission to perform this action</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID13</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has role USER</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">BusinessException(FORBIDDEN) - Your role does not have permission to perform this action</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID14</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Request has no valid JWT</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">BusinessException(UNAUTHORIZED)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID15</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; JWT is expired</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">BusinessException(UNAUTHORIZED)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID16</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role; Statistics repository throws exception</td><td style="text-align:left;">Default valid inputs</td><td style="text-align:left;">BusinessException(INTERNAL_ERROR)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr></tbody></table><hr><h2 id="_3-synchronization-verification-notes" tabindex="-1">3. Synchronization &amp; Verification Notes <a class="header-anchor" href="#_3-synchronization-verification-notes" aria-label="Permalink to &quot;3. Synchronization &amp; Verification Notes&quot;">​</a></h2><ul><li>Synchronized 1-to-1 with <a href="./../../../../brandhub-final_report/report5/Report5_Unit Test.xls.html"><code>Report5_Unit Test.xls</code></a> sheet <code>FR3.10.2</code>, <a href="./../../../../brandhub-final_report/report5/Report5_Test Report.xlsx.html"><code>Report5_Test Report.xlsx</code></a>, and <a href="./../../../../brandhub-final_report/report5/Report5_Test Documentation.docx.html"><code>Report5_Test Documentation.docx</code></a>.</li><li>Role names strictly follow the 6 canonical roles (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>).</li></ul><hr><h2 id="_4-feature-acceptance-integration-verification" tabindex="-1">4. Feature Acceptance &amp; Integration Verification <a class="header-anchor" href="#_4-feature-acceptance-integration-verification" aria-label="Permalink to &quot;4. Feature Acceptance &amp; Integration Verification&quot;">​</a></h2><h1 id="test-—-3-10-2-platform-statistics-overview" tabindex="-1">Test — 3-10-2-platform-statistics-overview <a class="header-anchor" href="#test-—-3-10-2-platform-statistics-overview" aria-label="Permalink to &quot;Test — 3-10-2-platform-statistics-overview&quot;">​</a></h1><p>Các kỳ vọng chi tiết: Acceptance Criteria/Edge Cases trong <a href="./spec.html">spec</a> và mục 5 của <a href="./../plan.html">plan kỹ thuật</a>.</p><ul><li><p>[x] Successful login trong 30 ngày (foundation)</p></li><li><p>[x] Refresh không tính: dùng lastLoginAt; đã đối chiếu writer login/2FA/OAuth, refresh không cập nhật</p></li><li><p>[ ] 3 ranking riêng</p></li><li><p>[x] Biên UTC/VN cho biểu đồ đăng ký foundation</p></li><li><p>[x] VI/EN và light/dark cho dashboard foundation</p></li><li><p>[x] Chưa đăng nhập401; USER gọi Admin403; ADMIN hợp lệ mới đọc được endpoint statistics foundation.</p></li><li><p>[ ] Lỗi server không báo thành công, không mất dữ liệu form; double click không ghi trùng.</p></li><li><p>[ ] Không trả passwordHash/otpCode/totpSecret hoặc token trong danh sách/audit.</p></li></ul><h2 id="ket-qua" tabindex="-1">Kết quả <a class="header-anchor" href="#ket-qua" aria-label="Permalink to &quot;Kết quả&quot;">​</a></h2><h3 id="dashboard-foundation-—-2026-10-02" tabindex="-1">Dashboard foundation — 2026-10-02 <a class="header-anchor" href="#dashboard-foundation-—-2026-10-02" aria-label="Permalink to &quot;Dashboard foundation — 2026-10-02&quot;">​</a></h3><ul><li>Backend: ADMIN200/USER403/anonymous401; days/timezone không hợp lệ400; aggregate không lẫn refresh với login, không đếm strike hết/gỡ/quy đổi; ngày thiếu được bù0; phân ngày UTC/VN đúng ở23:59/00:00; không trả PII.</li><li>UI: <code>/admin</code> mặc định Tổng quan; số thực từDTO; lỗi không chuyển thành0; đổi kỳ/timezone gửi đúng query; refresh/retry; không sửa cache người khác; drill-down mở danh sách đúng trạng thái; back/refresh giữview; tab Người dùng giữ các thao tác strike.</li><li>Visual: VI/EN, light/dark,1440px/390px; kiểm tra ảnh chụp, không tràn trang; keyboard/focus và nhãn biểu đồ; Admin không thấy ô chọn Agency. Mục chưa triển khai không có thao tác thành công giả.</li><li>Regression: tests account/strike và stale-session hiện có; update URL vào tab users nếu trước đây mặc định users.</li></ul><h3 id="ket-qua-foundation-ngay-2026-10-02" tabindex="-1">Kết quả foundation ngày 2026-10-02 <a class="header-anchor" href="#ket-qua-foundation-ngay-2026-10-02" aria-label="Permalink to &quot;Kết quả foundation ngày 2026-10-02&quot;">​</a></h3><ul><li>Backend:13/13 pass (<code>AdminStatisticsTest</code>5 PostgreSQL thật + <code>AdminSecurityTest</code>8 MVC/security),0 skip. Bao gồm30d login window, biên ngàyVN/UTC, bù ngày0, future timestamp, strike gỡ/hết/quy đổi, Agency soft delete theo cả timestamp/status, tổng phân bố bằng tổng user;401/403/Admin200. Log <code>.tmp/dashboard-data-final.log</code>.</li><li>Frontend:18/18 Playwright pass (9 overview,7 account,2 stale-login), gồm lỗi/retry,403 sau khi đã cache số liệu, search reset theo URL, mobile Admin navigation, trạng thái drill-down, VI/EN/light/dark. Log <code>.tmp/dashboard-ui-final.log</code>. Ảnh lưu ở <code>brandhub-web/test-results/admin-overview-*</code> và <code>admin-accounts-*</code>.</li><li>RED đã tái hiện trước sửa: thiếu dashboard; mobile Admin dùng nhầm nav Workspace; cached số liệu còn hiển thị sau403; search cũ còn trong input sau xóa URL filter. Logs <code>.tmp/dashboard-ui-red.log</code>, <code>.tmp/dashboard-mobile-red.log</code>, <code>.tmp/dashboard-review-red.log</code>. Fixture ngày đã sửa để không bị Hibernate CreationTimestamp ghi đè; không sửa model production để chiều test.</li><li>ESLint tất cả file frontend thay đổi và <code>npm run build</code>: pass; cảnh báo chunk lớn có sẵn vẫn còn. Logs <code>.tmp/dashboard-web-lint-final.log</code>, <code>.tmp/dashboard-web-build-final.log</code>.</li><li>Browser/HTTP không mock qua Gateway8080: loginAdmin thành công; statistics200 ở cảUTC/VN,7/30 mẫu ngày; filter sai400, anonymous401; mở danh sách và dialog thẻ phạt; không lỗi JavaScript. DevDB hiện2users,1active30d,0agency. <code>.tmp/dashboard-live.log</code>, script <code>.tmp/dashboard-live.cjs</code>; ảnh <code>.tmp/admin-dashboard-live-vi.png</code>, <code>.tmp/admin-users-live-vi.png</code>.</li><li>Review độc lập phát hiện2 lỗi UI nói trên, đã sửa và review lại không còn finding quan trọng trong phạm vi. Không chạy lại full suite có lỗi Workspace baseline vì không đổi Workspace business logic.</li></ul><p>Chỉ nghiệm thu foundation. Ba bảng xếp hạng Agency, tài chính/MRR/ARR, custom range, cache Redis và PDF vẫn thuộc bước sau; checklist toàn bộ FR ở trên không được coi là hoàn thành.</p><h2 id="ke-hoach-kiem-chung-ui-refinement-—-2026-10-04" tabindex="-1">Kế hoạch kiểm chứng UI refinement — 2026-10-04 <a class="header-anchor" href="#ke-hoach-kiem-chung-ui-refinement-—-2026-10-04" aria-label="Permalink to &quot;Kế hoạch kiểm chứng UI refinement — 2026-10-04&quot;">​</a></h2><ul><li>Dữ liệu KPI/chart/status từ API; không Trust Score/Super Admin/x/2, mock notification hay số tiền mẫu. Có KPI pendingSanctions, nhãn active 30 ngày rõ; đổi 7/30/90 và UTC/VN gửi đúng query.</li><li>Loading, lỗi/retry, refresh lỗi giữ chỉ báo stale; 403 bỏ toàn bộ số liệu đã cache. Tổng 0 không NaN, không tạo tỷ lệ giả.</li><li>Link trạng thái mở đúng URL; search/filter/reload/pagination/dialog/quyền xử phạt giữ hành vi cũ. Email/Revenue/Reports/Moderation ghi rõ chưa sẵn sàng.</li><li>VI/EN và light/dark; 375/768/1440px không tràn main, sidebar collapsed/mobile drawer; bảng cuộn bên trong; ảnh kiểm tra bằng mắt.</li><li>Build và ESLint các file đổi; Playwright overview/accounts/stale-session; browser smoke đăng nhập Admin và đọc API thật. Không thử mutation chế tài trên dữ liệu người dùng để chụp giao diện.</li></ul><p>Kết quả kiểm tra ngày 2026-10-04:</p><ul><li>Build frontend (<code>tsc -b</code> + <code>vite build</code>) thành công sau khi cài dependency của bản pull mới. ESLint các file thay đổi: 0 lỗi, 1 cảnh báo <code>react-hooks/set-state-in-effect</code> tại Sidebar trong logic hover/đóng Org Switcher có sẵn.</li><li>Playwright overview/accounts: 17/17 pass. Kiểm tra shell Admin bỏ chuông notification mock đã RED (chuông vẫn tồn tại), sau sửa GREEN. Các nhánh refresh/retry/403, URL/search, dialog/idempotency khi lỗi, VI/EN và sáng/tối vẫn pass.</li><li>Browser thật qua Gateway: đăng nhập Admin, statistics HTTP200, đổi UTC/VN, tìm tài khoản theo email và mở/đóng dialog thẻ phạt đều thành công; 0 lỗi JavaScript. Script <code>.tmp/dashboard-live.cjs</code>; ảnh <code>.tmp/admin-dashboard-live-vi.png</code>, <code>.tmp/admin-users-live-vi.png</code>.</li><li>Dữ liệu DB hiện đã được seed thêm: 1.242 users, 795 active30d, 46 Agency; không giả định Admin nằm trong trang tài khoản đầu tiên. Smoke script tìm kiếm trước khi kiểm tra tài khoản Admin.</li><li>Đã xem ảnh dashboard desktop thật và mobile dark từ Playwright. Web3000, Gateway8080, Business8081, AI8082, Publisher8083 đều phản hồi; Business health cần thời gian lâu hơn các dịch vụ khác nhưng trả UP.</li></ul><p>Phạm vi bằng chứng này là dashboard/accounts và khởi chạy hệ thống; không dùng để nghiệm thu toàn bộ FR tài chính, email, xuất PDF hoặc Monitoring.</p><ul><li>Kiểm tra bổ sung trên code hiện tại sau pull: overview + accounts + finance + stale-session, 24/24 Playwright pass (19,8 giây). Bao gồm đăng nhập mật khẩu/Dev Quick Login thay phiên cũ, giao diện doanh thu mobile light/dark, validation lịch email và export không tạo PDF rỗng. Các bài kiểm tra finance dùng API fixture nên không chứng nhận đã gửi email hay thanh toán thật.</li></ul>',26)])])}const y=e(l,[["render",s]]);export{u as __pageData,y as default};
